// Result is the output of Predict.
type Result struct {
	LeafID      uint16
	Count       uint8
	PurityMilli uint16
	PartBitset  [4]uint64
}

// Predict walks the decision tree for the given padded quantized query (16 i16s)
// and returns the matching leaf info.
func Predict(q [16]int16) Result {
	node := int32(0)
	for {
		n := nodes[node]
		if n.Left < 0 {
			leaf := uint16(-1 - n.Left)
			l := leaves[leaf]
			return Result{LeafID: leaf, Count: l.Count, PurityMilli: l.PurityMilli, PartBitset: l.PartBitset}
		}
		if q[n.Feat] <= n.Thr {
			node = n.Left
		} else {
			node = n.Right
		}
	}
}

// LeafSafeA reports whether the leaf is safe enough to skip the full KNN.
func LeafSafeA(leaf uint16) bool {
	if int(leaf) >= LeafCount {
		return false
	}
	return leafSafeA[leaf]
}

// LeafSafeB reports whether the leaf is safe under Mode B (partition routing).
